# ---- R/binary.R ----
# Binary layout derived from JMPReader.jl (Copyright 2024 Jaakko Ruohio)
# and jmp-convert (Copyright 2026 David Mathers), both MIT licensed.
# This is an independent, conservative reader; JMP's binary format is undocumented.

.jmp_corrupt <- function(message) .jmp_abort(message, "jmp_corrupt_error")

.jmp_slice <- function(x, start, n) {
  if (length(start) != 1L || length(n) != 1L || !is.finite(start) ||
      !is.finite(n) || start < 0 || n < 0 || start != floor(start) ||
      n != floor(n) || start + n > length(x))
    .jmp_corrupt("Invalid or truncated binary data range.")
  if (!n) raw() else x[seq.int(start + 1, length.out = n)]
}

.jmp_uint <- function(x, width, signed = FALSE) {
  if (!width %in% c(1L, 2L, 4L, 8L) || length(x) %% width)
    .jmp_corrupt("Invalid integer storage width.")
  if (!length(x)) return(numeric())
  m <- matrix(as.integer(x), nrow = width)
  if (width == 8L && signed) {
    low <- colSums(m[1:4, , drop = FALSE] * 256^(0:3))
    high <- colSums(m[5:8, , drop = FALSE] * 256^(0:3))
    high <- high - (m[8, ] >= 128) * 2^32
    return(low + high * 2^32)
  }
  value <- colSums(m * 256^(seq_len(width) - 1L))
  if (signed) value <- value - (m[width, ] >= 128) * 256^width
  value
}

.jmp_utf8 <- function(x, trailing_nul = FALSE) {
  if (trailing_nul && length(x)) {
    nonzero <- which(x != as.raw(0))
    x <- if (length(nonzero)) x[seq_len(nonzero[length(nonzero)])] else raw()
  }
  if (any(x == as.raw(0))) .jmp_corrupt("Embedded NUL in a text value.")
  s <- rawToChar(x)
  Encoding(s) <- "UTF-8"
  if (is.na(iconv(s, from = "UTF-8", to = "UTF-8", sub = NA)))
    .jmp_abort("Non-UTF-8 text is not supported; bytes are not replaced silently.",
               "jmp_encoding_error")
  s
}

.jmp_find <- function(x, pattern, start = 0) {
  if (start < 0 || start > length(x)) .jmp_corrupt("Invalid search offset.")
  possible <- which(x == pattern[1L]) - 1L
  possible <- possible[possible >= start & possible + length(pattern) <= length(x)]
  for (p in possible) if (identical(.jmp_slice(x, p, length(pattern)), pattern)) return(p)
  .jmp_corrupt("Required binary section marker was not found.")
}

.jmp_cursor <- function(x, pos = 0) {
  e <- new.env(parent = emptyenv())
  e$pos <- pos
  e$take <- function(n) {
    force(n)
    a <- .jmp_slice(x, e$pos, n)
    e$pos <- e$pos + n
    a
  }
  e$skip <- function(n) { e$take(n); invisible(NULL) }
  e$num <- function(w, signed = FALSE) {
    ans <- .jmp_uint(e$take(w), w, signed)
    if (w == 8L && (!is.finite(ans) || abs(ans) > 2^53 - 1))
      .jmp_corrupt("Binary length or offset exceeds exact integer range.")
    ans
  }
  e$str <- function(w) .jmp_utf8(e$take(e$num(w, TRUE)), TRUE)
  e$until <- function(p) { e$pos <- .jmp_find(x, p, e$pos) + length(p); invisible(NULL) }
  e
}

.jmp_header <- function(bytes, max_cells) {
  magic <- as.raw(c(255, 255, 0, 0, 7, 0, 0, 0, 4, 0, 0, 0, 1, 0, 1, 0, 2, 0))
  if (length(bytes) < length(magic) || !identical(bytes[seq_along(magic)], magic))
    .jmp_corrupt("This is not a supported JMP binary data table.")
  p <- .jmp_find(bytes, as.raw(c(7, 0, 8, 0, 0, 0))) - 32
  c <- .jmp_cursor(bytes, p)
  nr <- c$num(8, TRUE)
  nc <- c$num(4, TRUE)
  if (nr < 0 || nc < 0 || nr > max_cells || nc > max_cells || nr * nc > max_cells)
    .jmp_abort("The table dimensions exceed max_cells or are invalid.", "jmp_limit_error")
  if (nc > length(bytes) / 8) .jmp_corrupt("Impossible column count.")
  c$skip(10)
  charset <- c$str(4)
  c$skip(6)
  saved <- readBin(c$take(8), "double", 1L, size = 8L, endian = "little")
  c$skip(2)
  build <- c$str(4)
  table_header_offset <- c$pos
  c$pos <- 2
  repeat {
    c$until(as.raw(c(255, 255)))
    while (c$pos < length(bytes) && bytes[c$pos + 1] == as.raw(255)) c$pos <- c$pos + 1
    c$skip(10)
    visible <- c$num(4)
    hidden <- c$num(4)
    c$skip(8)
    if (visible + hidden == nc) break
    c$pos <- c$pos - 18
  }
  visible_idx <- .jmp_uint(c$take(4 * visible), 4)
  hidden_idx <- .jmp_uint(c$take(4 * hidden), 4)
  widths <- .jmp_uint(c$take(2 * nc), 2)
  c$skip(28)
  repeat {
    b <- as.integer(c$take(2))
    if (b[2] == 255 && b[1] %in% 252:255) c$skip(c$num(8, TRUE))
    else { c$pos <- c$pos - 2; break }
  }
  column_index_offset <- c$pos
  if (c$num(4, TRUE) != nc) .jmp_corrupt("The two column counts disagree.")
  offsets <- vapply(seq_len(nc), function(i) c$num(8, TRUE), numeric(1))
  if (any(offsets < 0 | offsets >= length(bytes)) || any(diff(offsets) <= 0))
    .jmp_corrupt("Invalid or unsorted column offsets.")
  names <- vapply(offsets, function(o) .jmp_cursor(bytes, o)$str(2), character(1))
  list(nrows = nr, ncols = nc, names = names, offsets = offsets, build = build,
       charset = charset, saved_jmp_seconds = saved, widths = widths,
       visible_indices = visible_idx, hidden_indices = hidden_idx,
       table_header_offset = table_header_offset, column_index_offset = column_index_offset)
}

.jmp_table_rows <- function(bytes, info) {
  # Recognize the bounded table-property directory, never search for flag bytes
  # in arbitrary scripts or column data. Unrecognized layouts remain unknown.
  c <- .jmp_cursor(bytes, info$table_header_offset)
  end <- info$column_index_offset
  if (end - c$pos < 20) return(NULL)
  if (c$num(2) != 5 || c$num(4) != 4) return(NULL)
  c$skip(4)
  if (.jmp_uint(.jmp_slice(bytes, c$pos, 2), 2) == 31) {
    c$skip(2)
    size <- c$num(4)
    if (size > end - c$pos - 10) return(NULL)
    c$skip(size)
  }
  count <- c$num(2)
  total <- c$num(8)
  if (c$pos + total != end || count * 10 > total) return(NULL)
  state <- NULL
  seen <- integer()
  for (i in seq_len(count)) {
    if (end - c$pos < 10) return(NULL)
    id <- c$num(2)
    size <- c$num(8)
    if (size > end - c$pos || id %in% seen) return(NULL)
    seen <- c(seen, id)
    if (id == 16) {
      # Each stored row state has eight bytes: color (4), flags (1),
      # marker (2), and a reserved byte (1). Other layouts remain unknown.
      if (size != info$nrows * 8) return(NULL)
      state <- c$take(size)
    } else c$skip(size)
  }
  if (c$pos != end || !65535 %in% seen) return(NULL)
  flags <- if (is.null(state)) rep(0L, info$nrows) else
    as.integer(state[seq.int(5, length.out = info$nrows, by = 8)])
  data.frame(row_id = seq_len(info$nrows),
             excluded = bitwAnd(flags, 2L) != 0L,
             hidden = bitwAnd(flags, 4L) != 0L,
             selected = bitwAnd(flags, 1L) != 0L,
             labelled = bitwAnd(flags, 8L) != 0L)
}

.jmp_properties <- function(bytes, after_dt, end, padding = 4) {
  # This block is only one known header layout. Failure is reported as unknown.
  tryCatch({
    c <- .jmp_cursor(bytes, after_dt)
    c$skip(padding)
    n <- c$num(2)
    total <- c$num(8)
    if (c$pos + total > end || n * 10 > total) return(NULL)
    start <- c$pos
    out <- lapply(seq_len(n), function(i) {
      id <- c$num(2)
      size <- c$num(8)
      if (c$pos + size > start + total) .jmp_corrupt("Invalid column property length.")
      list(id = id, payload = c$take(size))
    })
    if (c$pos - start != total) return(NULL)
    if (anyDuplicated(vapply(out, function(p) p$id, numeric(1)))) return(NULL)
    attr(out, "end_offset") <- c$pos
    out
  }, error = function(e) NULL)
}

.jmp_column_attributes <- function(bytes, pos, end) {
  if (is.null(pos)) return(NULL)
  tryCatch({
    c <- .jmp_cursor(bytes, pos)
    n <- c$num(2)
    total <- c$num(4)
    if (total > end - c$pos || n * 6 > total) return(NULL)
    stop_at <- c$pos + total
    out <- list()
    for (i in seq_len(n)) {
      if (stop_at - c$pos < 6) return(NULL)
      id <- as.character(c$num(2))
      size <- c$num(4)
      if (size > stop_at - c$pos || id %in% names(out)) return(NULL)
      out[[id]] <- c$take(size)
    }
    if (c$pos != stop_at) return(NULL)
    out
  }, error = function(e) NULL)
}

.jmp_literal_column_properties <- function(props, character_column) {
  # Property 7 is an inert length-prefixed JSL property expression, not code
  # to execute. Only complete literal missing-code/value-order declarations
  # are interpreted. Anything else leaves these properties unknown.
  unknown <- list(known = FALSE)
  if (is.null(props)) return(unknown)
  found <- Filter(function(p) p$id == 7, props)
  empty <- list(known = TRUE, missing_value_codes = NULL, value_order = NULL)
  if (!length(found)) return(empty)
  if (length(found) != 1L) return(unknown)
  tryCatch({
    b <- found[[1]]$payload
    c <- .jmp_cursor(b)
    nodes <- list()
    repeat {
      size <- c$num(4, TRUE)
      if (size == -1) break
      if (size < 0 || size > length(b) - c$pos) return(unknown)
      nodes <- c(nodes, .jrp_parse(.jmp_utf8(c$take(size))))
    }
    if (c$pos != length(b)) return(unknown)
    names <- vapply(nodes, function(node) {
      if (node$kind != "call") return("")
      .jrp_name(node$value)
    }, "")
    if (anyDuplicated(names) || any(!names %in% c("missingvaluecodes", "valueorder"))) return(unknown)
    out <- empty
    for (i in seq_along(nodes)) {
      node <- nodes[[i]]
      if (length(node$args) != 1L || !node$args[[1]]$kind %in% c("list", "matrix")) return(unknown)
      value <- .jrp_literal(node$args[[1]])
      if (!length(value)) value <- NULL
      else if (anyNA(value) || (character_column && !is.character(value)) ||
               (!character_column && !is.numeric(value))) return(unknown)
      out[[if (names[i] == "missingvaluecodes") "missing_value_codes" else "value_order"]] <- value
    }
    out
  }, error = function(e) unknown)
}

.jmp_null_strings <- function(x, n) {
  if (n < 0 || n > length(x) + 1) .jmp_corrupt("Invalid string count.")
  zeros <- which(x == as.raw(0))
  if (length(zeros) < n) .jmp_corrupt("Truncated terminated string sequence.")
  ends <- zeros[seq_len(n)]
  starts <- c(0, utils::head(ends, -1L))
  vapply(seq_len(n), function(i) .jmp_utf8(.jmp_slice(x, starts[i], ends[i] - starts[i] - 1)), character(1))
}

.jmp_value_labels <- function(payload, numeric_keys) {
  c <- .jmp_cursor(payload)
  n <- c$num(4)
  keys <- c$take(c$num(4))
  n2 <- c$num(4)
  labels <- c$take(c$num(4))
  if (n != n2 || c$pos != length(payload)) .jmp_corrupt("Malformed value labels.")
  labels <- .jmp_null_strings(labels, n)
  if (numeric_keys) {
    if (length(keys) != 8 * n) .jmp_corrupt("Malformed numeric value labels.")
    values <- readBin(keys, "double", n, size = 8, endian = "little")
  } else values <- .jmp_null_strings(keys, n)
  list(values = values, labels = labels)
}

.jmp_gunzip <- function(x, declared, limit) {
  if (declared < 0 || declared > limit)
    .jmp_abort("Decompressed column exceeds the resource limit.", "jmp_limit_error")
  if (length(x) < 18 || !identical(x[1:3], as.raw(c(31, 139, 8))))
    .jmp_corrupt("Compressed column does not contain a valid gzip header.")
  con <- gzcon(rawConnection(x, "rb"), allowNonCompressed = FALSE)
  on.exit(close(con))
  out <- list()
  total <- 0
  withCallingHandlers({
    repeat {
      chunk <- readBin(con, "raw", n = min(1048576, declared - total + 1))
      if (!length(chunk)) break
      total <- total + length(chunk)
      if (total > declared) .jmp_corrupt("Decompressed size exceeds the column header.")
      out[[length(out) + 1L]] <- chunk
    }
  }, warning = function(w) .jmp_corrupt(paste("Invalid gzip column:", conditionMessage(w))))
  if (total != declared) .jmp_corrupt("Truncated gzip column.")
  do.call(c, c(out, list(raw())))
}

.jmp_numbers <- function(a, width, n) {
  if (!width %in% c(1, 2, 4, 8)) width <- 8
  bytes <- .jmp_slice(a, length(a) - width * n, width * n)
  if (width == 8) {
    v <- readBin(bytes, "double", n, size = 8, endian = "little")
    v[is.nan(v)] <- NA_real_
  } else {
    v <- .jmp_uint(bytes, width, TRUE)
    v[v == -2^(width * 8 - 1) + 1] <- NA_real_
    # R reserves the smallest 32-bit integer for NA: retain doubles in this case.
    if (!any(v == -2147483648, na.rm = TRUE)) v <- as.integer(v)
  }
  v
}

.jmp_temporal <- function(a, b) {
  same <- a == b
  pair <- paste(a, b, sep = ":")
  if ((same && a %in% c(101,102,103,110,111,112,113,114,117,118,122,127,136,139)) ||
      pair %in% c("103:101","111:101","114:101","114:111","114:127","114:128","127:114","136:101","136:122")) return("date")
  if ((b %in% c(105,106,115,116,119,120,126,129) &&
       a %in% c(105,106,108,109,115,116,119,120,121,123,124,125,126,128,129,130,134,135,137,138)) ||
      (same && b %in% c(121,125)) || pair %in% c("119:128","119:127","137:101")) return("datetime")
  if (same && b == 130) return("time")
  if ((same && a %in% c(12,107,108,109,131,132,133)) || pair == "132:121") return("duration")
  NULL
}

.jmp_i64_decimal <- function(x) {
  # Return exact decimal strings rather than rounding integers beyond 2^53.
  vapply(seq_len(length(x) / 8), function(i) {
    b <- as.integer(.jmp_slice(x, (i - 1) * 8, 8))
    neg <- b[8] >= 128
    if (neg) {
      b <- 255 - b
      carry <- 1
      for (j in 1:8) { z <- b[j] + carry; b[j] <- z %% 256; carry <- z %/% 256 }
    }
    digits <- 0
    for (j in 8:1) {
      digits <- digits * 256
      digits[1] <- digits[1] + b[j]
      k <- 1L
      while (k <= length(digits)) {
        carry <- digits[k] %/% 10
        digits[k] <- digits[k] %% 10
        if (carry) {
          if (k == length(digits)) digits <- c(digits, 0)
          digits[k + 1L] <- digits[k + 1L] + carry
        }
        k <- k + 1L
      }
    }
    paste0(if (neg) "-" else "", paste(rev(digits), collapse = ""))
  }, character(1))
}

.jmp_split_strings <- function(bytes, widths) {
  if (any(!is.finite(widths) | widths < 0) || sum(widths) > length(bytes))
    .jmp_corrupt("Invalid string widths.")
  starts <- c(0, utils::head(cumsum(widths), -1L))
  vapply(seq_along(widths), function(i) .jmp_utf8(.jmp_slice(bytes, starts[i], widths[i])), character(1))
}

.jmp_read_column <- function(bytes, info, i, max_cells, budget = NULL) {
  n <- info$nrows
  offset <- info$offsets[i]
  end <- if (i < info$ncols) info$offsets[i + 1L] else length(bytes)
  c <- .jmp_cursor(bytes, offset)
  name <- c$str(2)
  dt <- as.integer(c$take(6))
  after <- c$pos
  props <- .jmp_properties(bytes, after, end, if (dt[1] %in% c(1, 10)) 5 else 4)
  attrs <- .jmp_column_attributes(bytes, attr(props, "end_offset"), end)
  compressed <- dt[1] %in% c(9, 10)
  if (compressed) {
    c$until(as.raw(c(239, 190, 254, 202)))
    compressed_size <- c$num(8)
    unpacked_size <- c$num(8)
    if (c$pos + compressed_size > end) .jmp_corrupt("Compressed data crosses column boundary.")
    if (!is.null(budget)) {
      if (unpacked_size > budget$remaining)
        .jmp_abort("Total decompressed columns exceed 512 MiB.", "jmp_limit_error")
      budget$remaining <- budget$remaining - unpacked_size
    }
    a <- .jmp_gunzip(c$take(compressed_size), unpacked_size,
                    min(536870912, max(1048576, max_cells * 128)))
  } else a <- .jmp_slice(bytes, offset, end - offset)
  width <- function(w) if (w %in% c(1, 2, 4)) w else 8
  meta <- list(name = name, storage_type = NULL, modeling_type = NA_character_,
               format = list(codes = dt[4:5], width = dt[3]), value_labels = NULL,
               properties = list(), formula = NULL, raw_properties = props,
               type_bytes = as.raw(dt), display_width = info$widths[i],
               metadata_complete = FALSE,
               metadata_known = list(modeling_type = FALSE, missing_value_codes = FALSE,
                                     value_order = FALSE, value_labels = !is.null(props),
                                     units = FALSE, formula = FALSE))
  extra <- character()
  if (length(attrs[["23"]]) == 2L) {
    code <- .jmp_uint(attrs[["23"]], 2)
    if (code %in% 0:3) {
      meta$modeling_type <- c("Continuous", "Ordinal", "Nominal", "RowState")[code + 1L]
      meta$metadata_known$modeling_type <- TRUE
    }
  }
  if (dt[1] %in% c(1, 10, 255, 254, 252)) {
    w <- width(if (dt[1] %in% c(255, 254, 252)) dt[5] else dt[6])
    v <- .jmp_numbers(a, w, n)
    meta$storage_type <- if (w == 8) "Float64" else paste0("Int", w * 8)
    kind <- if (dt[1] %in% c(1, 10)) .jmp_temporal(dt[4], dt[5]) else NULL
    if (!is.null(kind)) {
      meta$temporal_kind <- kind
      meta$raw_values <- v
      meta$epoch <- "1904-01-01"
      meta$timezone <- NA_character_
      if (kind == "date") v <- as.Date(floor(v / 86400), origin = "1904-01-01")
      if (kind %in% c("time", "duration")) v <- as.difftime(v, units = "secs")
      if (kind == "datetime") {
        # UTC is a display convention only, not an assertion about the source timezone.
        v <- as.POSIXct(v, origin = "1904-01-01", tz = "UTC")
        extra <- c(extra, "Datetime timezone is unknown; UTC is used only as a display convention. Original seconds are retained.")
      }
    } else if (dt[1] %in% c(1, 10) &&
               !((dt[4] == dt[5] && dt[4] %in% c(0,3,66,67,68,89,96,99,95,81:86)) || dt[5] %in% c(94,99))) {
      extra <- c(extra, "Unrecognized number display format; stored numeric values and format codes retained.")
    }
  } else if (dt[1] == 3 && dt[2] == 3) {
    v <- .jmp_i64_decimal(.jmp_slice(a, length(a) - 8 * n, 8 * n))
    meta$storage_type <- "Int64"
    extra <- c(extra, "64-bit integers are exact decimal strings to avoid R double precision loss.")
  } else if (dt[1] == 9 && dt[2] == 3) {
    markers <- c("\u2022", "+", "X", "\u25a1", "\u25ca", "\u25b3", "Y", "Z", "\u25ef", "\u25ad", "\u25af", "*", "\u26ab", "\u25ac", "\u25ae", "\u25a0", "\u29eb", "\u25bd", "\u25c1", "\u25b7", "\u25b2", "\u25bc", "\u25c0", "\u25b6", "\u2227", "\u2228", "<", ">", "\u2223", "\u2500", "/", "\\")
    colors <- c("000000","555555","787878","C0C0C0","FFFFFF","A00922","C91629","F03246","FF5C76","FF98A6","904700","BC5B03","E57406","FF9138","FFB17D","706F00","AFA502","DAD109","F0E521","FFF977","516A00","729400","90BF04","A2DC06","C1FF3D","00670C","11981B","21BC2D","23E72E","6AFF6B","007254","019970","04C791","06E3AA","0FFFBC","006D71","01989C","0CBCBC","06E2E3","67FFF7","00638F","0380B4","05A1D2","08C5F7","75E4FF","034AB0","0557D6","2867FD","4E9CFF","7E89FF","6A02A7","8C05CF","AB08FC","C170FF","D29AFF","930195","B803B9","DC06E1","FA50FF","FD96FF","9D0170","C5048D","E906A4","FF49BC","FF8CCD")
    if (dt[5] < 7) .jmp_corrupt("Invalid row state width.")
    state <- lapply(seq_len(n), function(r) {
      b <- as.integer(.jmp_slice(a, (r - 1) * dt[5], 7))
      idx <- b[6] + 256 * b[7]
      marker <- if (idx < length(markers)) markers[idx + 1] else intToUtf8(idx)
      color <- if (b[4] == 255) paste(sprintf("%02X", b[3:1]), collapse = "") else {
        if (b[1] >= length(colors)) .jmp_abort("Unknown row state palette index.", "jmp_unsupported_error")
        colors[b[1] + 1]
      }
      c(marker = marker, color = paste0("#", color))
    })
    meta$row_states <- data.frame(marker = vapply(state, `[[`, "", "marker"),
                                  color = vapply(state, `[[`, "", "color"), stringsAsFactors = FALSE)
    meta$raw_row_states <- a
    meta$storage_type <- "RowState"
    v <- paste(meta$row_states$marker, meta$row_states$color)
    extra <- c(extra, "Row-state column marker/color decoded; other state bits retained as raw bytes, not interpreted.")
  } else if (dt[1] %in% c(2, 9) && dt[2] %in% c(1, 2)) {
    meta$storage_type <- "Character"
    pool_prop <- Filter(function(p) p$id == 4, props)
    if (dt[3] == 0 && dt[4] == 0 && dt[5] %in% c(1,2,4) && length(pool_prop)) {
      p <- .jmp_cursor(pool_prop[[1]]$payload)
      np <- p$num(2)
      pool <- .jmp_null_strings(p$take(length(pool_prop[[1]]$payload) - p$pos), np)
      idx <- .jmp_uint(.jmp_slice(a, length(a) - n * dt[5], n * dt[5]), dt[5])
      bad <- idx >= length(pool)
      if (any(bad & idx != 256^dt[5] - 1)) .jmp_corrupt("Invalid coded string index.")
      v <- rep("", n)
      v[!bad] <- pool[idx[!bad] + 1]
    } else if ((dt[3] == 0 && dt[4] == 0 && dt[5] > 0) || (dt[3] %in% 1:7 && dt[4] == 0)) {
      w <- dt[5]
      if (!w && n) .jmp_corrupt("Zero fixed string width.")
      data <- .jmp_slice(a, length(a) - n * w, n * w)
      v <- vapply(seq_len(n), function(r) {
        s <- .jmp_slice(data, (r - 1) * w, w)
        zero <- which(s == as.raw(0))
        if (length(zero)) s <- .jmp_slice(s, 0, zero[1] - 1)
        .jmp_utf8(s)
      }, character(1))
    } else if (all(dt[3:5] == 0)) {
      if (compressed) {
        p <- .jmp_cursor(a)
        if (p$num(8, TRUE) == length(a)) {
          p$skip(9)
          p$num(8, TRUE)
          w <- p$num(1, TRUE)
          if (!w %in% c(1,2,4)) .jmp_corrupt("Unknown compact string index width.")
          idx <- .jmp_uint(p$take(w * n), w)
          np <- max(c(0, idx))
          if (np > n || np > length(a)) .jmp_corrupt("Invalid compact string pool count.")
          lw <- p$num(1, TRUE)
          if (!lw %in% c(1,2)) .jmp_corrupt("Unknown compact string length width.")
          pool <- vapply(seq_len(np), function(k) .jmp_utf8(p$take(p$num(lw, TRUE))), character(1))
          v <- rep("", n)
          v[idx > 0] <- pool[idx[idx > 0]]
        } else {
          w <- as.integer(.jmp_slice(a, 8, 1))
          if (!w %in% c(1,2)) .jmp_corrupt("Unknown compressed string length width.")
          widths <- .jmp_uint(.jmp_slice(a, 13, n * w), w, TRUE)
          v <- .jmp_split_strings(.jmp_slice(a, 13 + n * w, length(a) - 13 - n * w), widths)
        }
      } else {
        p <- .jmp_cursor(bytes, after)
        p$skip(6)
        p$skip(p$num(8, TRUE))
        p$skip(2)
        p$skip(p$num(4) + 8)
        w <- p$num(1)
        p$num(4)
        if (!w %in% c(1,2,4)) .jmp_corrupt("Unknown string length width.")
        widths <- .jmp_uint(p$take(w * n), w, TRUE)
        total <- sum(widths)
        if (any(widths < 0) || total > end - offset) .jmp_corrupt("Invalid string data size.")
        v <- .jmp_split_strings(.jmp_slice(bytes, end - total, total), widths)
      }
    } else .jmp_abort(paste("Unsupported string layout in", name), "jmp_unsupported_error")
  } else .jmp_abort(paste("Unsupported binary column type in", name,
                          paste(sprintf("%02x", dt), collapse = ":")), "jmp_unsupported_error")
  labels <- Filter(function(p) p$id == 14, props)
  if (length(labels)) {
    meta$value_labels <- tryCatch(.jmp_value_labels(labels[[1]]$payload,
      !identical(meta$storage_type, "Character")), error = function(e) {
        .jmp_abort(paste("Cannot decode value labels in", name, ":", conditionMessage(e)), "jmp_unsupported_error")
      })
  }
  literal <- if (is.null(attrs)) list(known = FALSE) else
    .jmp_literal_column_properties(props, identical(meta$storage_type, "Character"))
  if (isTRUE(literal$known)) {
    meta$missing_value_codes <- literal$missing_value_codes
    meta$value_order <- literal$value_order
    meta$metadata_known$missing_value_codes <- TRUE
    meta$metadata_known$value_order <- TRUE
  }
  if (!meta$metadata_known$modeling_type)
    extra <- c(extra, "Modeling type is unavailable or unsupported; it was not inferred from storage type.")
  if (!meta$metadata_known$missing_value_codes)
    extra <- c(extra, "Missing-value definitions and value order could not be fully interpreted; no absence was assumed.")
  if (identical(meta$modeling_type, "Ordinal") && !length(meta$value_order))
    extra <- c(extra, "Ordinal modeling type is retained, but category order is not explicit; see the ordinal_order conversion option.")
  list(values = v, metadata = meta, messages = extra)
}

.read_jmp_binary <- function(bytes, max_cells = 1e7) {
  info <- .jmp_header(bytes, max_cells)
  rows <- .jmp_table_rows(bytes, info)
  budget <- new.env(parent = emptyenv())
  budget$remaining <- 536870912
  columns <- lapply(seq_len(info$ncols), function(i) .jmp_read_column(bytes, info, i, max_cells, budget))
  data <- lapply(columns, `[[`, "values")
  names(data) <- info$names
  data <- structure(data, class = "data.frame", row.names = .set_row_names(info$nrows))
  meta <- lapply(columns, `[[`, "metadata")
  names(meta) <- info$names
  diagnostics <- data.frame(code = "binary_metadata_partial", scope = "table",
    message = "Binary reader retains supported modeling types, literal missing-code definitions, storage, format and value-label metadata. Units, formulas, table scripts and other properties are not fully decoded; check each column's metadata_known flags.",
    stringsAsFactors = FALSE)
  if (is.null(rows)) diagnostics <- rbind(diagnostics, data.frame(
    code = "table_row_states_unavailable", scope = "rows",
    message = "Table row-state layout is unsupported. Exclusion, hidden and selection states are unknown; row-state columns are separate."))
  for (i in seq_along(columns)) for (m in columns[[i]]$messages)
    diagnostics <- rbind(diagnostics, data.frame(code = "representation", scope = info$names[i], message = m, stringsAsFactors = FALSE))
  list(data = data, columns = meta, rows = rows,
       table = info[c("build", "charset", "saved_jmp_seconds", "nrows", "ncols", "visible_indices", "hidden_indices")],
       scripts = list(), diagnostics = diagnostics)
}

# ---- R/jrp.R ----
# A deliberately small JSL reader. This file never executes JSL or R code.
# The accepted grammar is described in README.md; unsupported input is an error.

.jrp_name <- function(x) gsub("[[:space:]_]", "", tolower(x))

.jrp_error <- function(message, subclass = "jrp_syntax_error", position = NULL) {
  if (!is.null(position)) message <- paste0(message, " (character ", position, ")")
  .jmp_abort(message, subclass = subclass)
}

.jrp_lex <- function(text) {
  n <- nchar(text, type = "chars")
  if (n > 16000000L) .jrp_error("JRP text exceeds the 16 million character limit.", "jmp_resource_error")
  z <- strsplit(text, "", fixed = TRUE)[[1L]]
  out <- vector("list", min(n + 1L, 10000L))
  nt <- 0L
  emit <- function(type, value, start, end) {
    nt <<- nt + 1L
    if (nt > 1000000L) .jrp_error("JRP token limit exceeded.", "jmp_resource_error", start)
    out[[nt]] <<- list(type = type, value = value, start = start, end = end)
  }
  i <- 1L
  while (i <= n) {
    c <- z[[i]]
    if (grepl("[[:space:]]", c)) { i <- i + 1L; next }
    if (c == "/" && i < n && z[[i + 1L]] == "/") {
      i <- i + 2L
      while (i <= n && !z[[i]] %in% c("\n", "\r")) i <- i + 1L
      next
    }
    if (c == "/" && i < n && z[[i + 1L]] == "*") {
      start <- i
      i <- i + 2L
      while (i < n && !(z[[i]] == "*" && z[[i + 1L]] == "/")) i <- i + 1L
      if (i >= n) .jrp_error("Unterminated block comment.", position = start)
      i <- i + 2L
      next
    }
    if (c == '"') {
      start <- i
      i <- i + 1L
      value <- character()
      run <- i
      while (i <= n && z[[i]] != '"') {
        if (z[[i]] == "\\" && i + 1L <= n && z[[i + 1L]] == "!") {
          if (i > run) value <- c(value, substr(text, run, i - 1L))
          if (i + 2L > n) .jrp_error("Incomplete JSL string escape.", position = i)
          escape <- z[[i + 2L]]
          replacement <- switch(escape, n = "\n", N = "\n", r = "\r", R = "\r",
                                t = "\t", T = "\t", '"' = '"', "\\" = "\\", NULL)
          if (is.null(replacement)) .jrp_error("Unsupported JSL string escape.", position = i)
          value <- c(value, replacement)
          i <- i + 3L
          run <- i
        } else i <- i + 1L
      }
      if (i > n) .jrp_error("Unterminated quoted string.", position = start)
      if (i > run) value <- c(value, substr(text, run, i - 1L))
      emit("string", paste0(value, collapse = ""), start, i)
      i <- i + 1L
      next
    }
    if (grepl("[0-9]", c) || (c == "." && i < n && grepl("[0-9]", z[[i + 1L]]))) {
      start <- i
      tail <- substr(text, i, min(n, i + 127L))
      number <- regmatches(tail, regexpr("^(?:[0-9]+(?:\\.[0-9]*)?|\\.[0-9]+)(?:[eE][+-]?[0-9]+)?", tail, perl = TRUE))
      i <- i + nchar(number)
      val <- suppressWarnings(as.numeric(number))
      if (!is.finite(val)) .jrp_error("Non-finite numeric literal is not supported.", position = start)
      emit("number", val, start, i - 1L)
      next
    }
    if (grepl("[[:alpha:]_]", c)) {
      start <- i
      i <- i + 1L
      while (i <= n && grepl("[[:alnum:]_ ]", z[[i]])) i <- i + 1L
      value <- trimws(substr(text, start, i - 1L))
      emit("ident", value, start, i - 1L)
      next
    }
    if (c %in% strsplit("()[]{},;=.+-*/:^<>!|&", "", fixed = TRUE)[[1L]]) {
      emit(c, c, i, i)
      i <- i + 1L
      next
    }
    .jrp_error(paste0("Unsupported character '", c, "'."), position = i)
  }
  out <- out[seq_len(nt)]
  out[[nt + 1L]] <- list(type = "eof", value = "", start = n + 1L, end = n + 1L)
  out
}

.jrp_parse <- function(text) {
  tokens <- .jrp_lex(text)
  # Scan call tokens, not raw strings: comments and quoted 'Open(...)' are data.
  external <- c("open", "include", "loadtextfile", "loadfile", "importdata",
                "opendatabase", "newsqlquery", "sqlquery", "newhttprequest",
                "httprequest", "downloadfile", "rsendfile", "pythonimport")
  dynamic <- c("eval", "evalexpr", "parse", "function", "for", "foreach", "while",
               "if", "runprogram", "runscript", "execute", "wait", "schedule",
               "pythonsubmit", "pythonsubmitfile", "rsubmit", "rsubmitfile",
               "randomnormal", "randomuniform")
  if (length(tokens) > 1L) for (k in seq_len(length(tokens) - 1L)) {
    if (tokens[[k]]$type == "ident" && tokens[[k + 1L]]$type == "(") {
      name <- .jrp_name(tokens[[k]]$value)
      if (name %in% external) .jrp_error(paste0("External data/reference call is not allowed: ", tokens[[k]]$value, "()."), "jrp_external_reference_error", tokens[[k]]$start)
      if (name %in% dynamic) .jrp_error(paste0("Dynamic JSL is not allowed: ", tokens[[k]]$value, "()."), "jrp_dynamic_error", tokens[[k]]$start)
    }
  }
  p <- 1L
  peek <- function() tokens[[p]]
  take <- function(type = NULL) {
    token <- peek()
    if (!is.null(type) && token$type != type) .jrp_error(paste0("Expected '", type, "', found '", token$type, "'."), position = token$start)
    p <<- p + 1L
    token
  }
  node <- function(kind, value = NULL, args = NULL, start, end) list(kind = kind, value = value, args = args, start = start, end = end)
  expression <- NULL
  collection <- function(close, depth) {
    args <- list()
    if (peek()$type == close) { take(close); return(args) }
    repeat {
      args[[length(args) + 1L]] <- expression(depth + 1L)
      if (peek()$type == close) { take(close); break }
      take(",")
      if (peek()$type == close) .jrp_error("Trailing commas are not supported.", position = peek()$start)
    }
    args
  }
  expression <- function(depth = 0L) {
    if (depth > 64L) .jrp_error("JRP nesting limit exceeded.", "jmp_resource_error", peek()$start)
    token <- take()
    if (token$type %in% c("number", "string")) {
      x <- node(token$type, token$value, start = token$start, end = token$end)
    } else if (token$type == ".") {
      x <- node("number", NA_real_, start = token$start, end = token$end)
    } else if (token$type %in% c("+", "-")) {
      value <- take("number")
      x <- node("number", if (token$type == "-") -value$value else value$value, start = token$start, end = value$end)
    } else if (token$type %in% c("[", "{")) {
      close <- if (token$type == "[") "]" else "}"
      args <- collection(close, depth)
      x <- node(if (token$type == "[") "matrix" else "list", args = args, start = token$start, end = tokens[[p - 1L]]$end)
    } else if (token$type == "ident") {
      if (peek()$type != "(") {
        x <- node("symbol", token$value, start = token$start, end = token$end)
      } else {
        take("(")
        if (.jrp_name(token$value) == "formula") {
          # Formula source is retained without interpretation. Only stored Values
          # can supply data. Bracket balancing still validates its container.
          first <- peek()$start
          formula_start <- p
          stack <- ")"
          while (length(stack)) {
            t <- take()
            if (t$type == "eof") .jrp_error("Unterminated Formula().", position = token$start)
            if (t$type %in% c("(", "[", "{")) {
              stack <- c(stack, switch(t$type, "(" = ")", "[" = "]", "{" = "}"))
              if (length(stack) + depth > 64L) .jrp_error("JRP nesting limit exceeded.", "jmp_resource_error", t$start)
            } else if (t$type %in% c(")", "]", "}")) {
              if (t$type != stack[[length(stack)]]) .jrp_error("Mismatched Formula() delimiter.", position = t$start)
              stack <- head(stack, -1L)
            }
          }
          formula_tokens <- tokens[seq.int(formula_start, p - 1L)]
          safe_formula_calls <- c("abs", "sqrt", "log", "log10", "exp", "power", "round",
                                  "floor", "ceiling", "min", "max", "sum", "mean")
          for (fi in seq_along(formula_tokens)) {
            ft <- formula_tokens[[fi]]
            if (ft$type %in% c(";", "=")) .jrp_error("Assignments or statements inside Formula() are not supported.", "jrp_dynamic_error", ft$start)
            if (ft$type == "ident" && fi < length(formula_tokens) &&
                formula_tokens[[fi + 1L]]$type == "(" && !.jrp_name(ft$value) %in% safe_formula_calls) {
              .jrp_error("Unsupported function inside Formula(); only simple arithmetic formula source is accepted.", "jrp_dynamic_error", ft$start)
            }
          }
          x <- node("formula", substr(text, first, t$start - 1L), start = token$start, end = t$end)
        } else {
          args <- collection(")", depth)
          x <- node("call", token$value, args, token$start, tokens[[p - 1L]]$end)
        }
      }
    } else .jrp_error("Expected a literal value or a supported declaration.", "jrp_dynamic_error", token$start)
    if (peek()$type == "=") {
      take("=")
      rhs <- expression(depth + 1L)
      x <- node("pair", args = list(x, rhs), start = x$start, end = rhs$end)
    }
    x
  }
  result <- list()
  while (peek()$type != "eof") {
    result[[length(result) + 1L]] <- expression()
    if (peek()$type == ";") take(";")
    else if (peek()$type != "eof") .jrp_error("Unexpected trailing or dynamic JSL expression.", "jrp_dynamic_error", peek()$start)
  }
  result
}

.jrp_literal <- function(x, descriptors = FALSE) {
  if (x$kind %in% c("number", "string")) return(x$value)
  if (x$kind %in% c("matrix", "list")) {
    values <- lapply(x$args, .jrp_literal, descriptors = descriptors)
    if (!length(values)) return(if (x$kind == "matrix") numeric() else list())
    scalar <- vapply(values, function(v) is.atomic(v) && length(v) == 1L, logical(1))
    kinds <- vapply(values, typeof, character(1))
    if (all(scalar) && length(unique(kinds)) == 1L) return(unlist(values, use.names = FALSE))
    return(values)
  }
  if (x$kind == "pair") return(list(key = .jrp_literal(x$args[[1L]], descriptors), value = .jrp_literal(x$args[[2L]], descriptors)))
  descriptor_names <- c("lsl", "usl", "target", "showlimits", "commonorder", "roworderlevels",
                        "reverseorder", "customorder", "valueorder", "color", "min", "max", "inc")
  if (descriptors && x$kind == "call" && .jrp_name(x$value) %in% descriptor_names) {
    return(list(jsl_call = x$value, arguments = lapply(x$args, .jrp_literal, descriptors = TRUE)))
  }
  .jrp_error("A value requires dynamic or unsupported JSL; only literals are accepted.", "jrp_dynamic_error", x$start)
}

.jrp_labels <- function(x) {
  if (!x$kind %in% c("list", "matrix") || !all(vapply(x$args, function(a) a$kind == "pair", logical(1)))) {
    .jrp_error("Value Labels must use literal code = label pairs.", "jrp_dynamic_error", x$start)
  }
  codes <- lapply(x$args, function(a) .jrp_literal(a$args[[1L]]))
  labels <- lapply(x$args, function(a) .jrp_literal(a$args[[2L]]))
  if (any(!vapply(codes, function(v) is.atomic(v) && length(v) == 1L, logical(1))) ||
      any(!vapply(labels, function(v) is.character(v) && length(v) == 1L, logical(1)))) {
    .jrp_error("Value labels require scalar codes and character labels.", position = x$start)
  }
  if (length(unique(vapply(codes, typeof, character(1)))) > 1L) .jrp_error("Value label codes must have one type.", position = x$start)
  codes <- unlist(codes, use.names = FALSE)
  if (anyDuplicated(codes)) .jrp_error("Duplicate value label codes.", position = x$start)
  list(values = codes, labels = unlist(labels, use.names = FALSE))
}

.read_jrp_text <- function(text, max_cells = 1e7) {
  declarations <- .jrp_parse(text)
  table <- NULL
  for (d in declarations) {
    if (d$kind == "call" && .jrp_name(d$value) == "namesdefaulttohere" &&
        length(d$args) == 1L && identical(.jrp_literal(d$args[[1L]]), 1)) next
    if (d$kind == "pair" && d$args[[1L]]$kind == "symbol") d <- d$args[[2L]]
    if (d$kind != "call" || .jrp_name(d$value) != "newtable") .jrp_error("Only one literal New Table() declaration is supported; report or dynamic commands are not executed.", "jrp_dynamic_error", d$start)
    if (!is.null(table)) .jrp_error("Multiple embedded tables are not yet supported.", "jmp_unsupported_error", d$start)
    table <- d
  }
  if (is.null(table)) .jrp_error("No embedded New Table() data were found.", "jmp_unsupported_error")
  if (!length(table$args) || table$args[[1L]]$kind != "string") .jrp_error("New Table() requires a literal table name.", "jrp_dynamic_error", table$start)
  table_name <- table$args[[1L]]$value
  row_count <- NULL
  columns <- list()
  values <- list()
  table_properties <- list()
  diagnose <- list()
  diagnostic <- function(code, scope, message) {
    diagnose[[length(diagnose) + 1L]] <<- data.frame(code = code, scope = scope, message = message, stringsAsFactors = FALSE)
  }
  call_name <- function(x) if (x$kind == "call") .jrp_name(x$value) else ""
  for (a in table$args[-1L]) {
    name <- call_name(a)
    if (name == "addrows") {
      if (!is.null(row_count) || length(a$args) != 1L) .jrp_error("Add Rows() must occur once with one integer.", position = a$start)
      row_count <- .jrp_literal(a$args[[1L]])
      if (!is.numeric(row_count) || length(row_count) != 1L || is.na(row_count) ||
          !is.finite(row_count) || row_count < 0 || row_count != floor(row_count)) .jrp_error("Invalid Add Rows() count.", position = a$start)
      if (row_count > max_cells) .jrp_error("JRP row count exceeds max_cells.", "jmp_resource_error", a$start)
    } else if (name == "newcolumn") {
      if (!length(a$args) || a$args[[1L]]$kind != "string") .jrp_error("New Column() requires a literal name.", "jrp_dynamic_error", a$start)
      cn <- a$args[[1L]]$value
      if (!nzchar(cn) || cn %in% names(columns)) .jrp_error("Empty or duplicate column names are not supported.", position = a$start)
      meta <- list(name = cn, storage_type = "numeric", modeling_type = "Continuous", format = NULL,
                   value_labels = NULL, missing_value_codes = NULL, value_order = NULL,
                   metadata_known = list(modeling_type = TRUE, missing_value_codes = TRUE,
                                         value_order = TRUE, value_labels = TRUE),
                   properties = list(), formula = NULL, raw_properties = list())
      v <- NULL
      have_values <- FALSE
      seen <- character()
      for (b in a$args[-1L]) {
        bn <- call_name(b)
        if (b$kind %in% c("symbol", "string")) {
          word <- .jrp_name(b$value)
          if (word %in% c("numeric", "character")) {
            if ("type" %in% seen) .jrp_error("Duplicate column storage type.", position = b$start)
            seen <- c(seen, "type")
            meta$storage_type <- word
          } else if (word %in% c("continuous", "nominal", "ordinal")) {
            if ("model" %in% seen) .jrp_error("Duplicate modeling type.", position = b$start)
            seen <- c(seen, "model")
            meta$modeling_type <- paste0(toupper(substr(word, 1L, 1L)), substring(word, 2L))
          } else .jrp_error("Unsupported column declaration.", "jrp_dynamic_error", b$start)
        } else if (bn %in% c("values", "setvalues")) {
          if (have_values || length(b$args) != 1L) .jrp_error("Each column requires one Values() or Set Values() argument.", position = b$start)
          v <- .jrp_literal(b$args[[1L]])
          if (is.list(v) && !length(v)) v <- character()
          if (!is.atomic(v) || is.null(v)) .jrp_error("Column values must be a homogeneous literal vector.", "jrp_dynamic_error", b$start)
          have_values <- TRUE
        } else if (bn == "format") {
          if (!is.null(meta$format)) .jrp_error("Duplicate Format().", position = b$start)
          meta$format <- lapply(b$args, .jrp_literal)
        } else if (bn == "setproperty") {
          if (length(b$args) != 2L || b$args[[1L]]$kind != "string") .jrp_error("Set Property() requires a literal name and value.", "jrp_dynamic_error", b$start)
          property_name <- b$args[[1L]]$value
          if (.jrp_name(property_name) %in% .jrp_name(names(meta$properties))) .jrp_error("Duplicate column property.", position = b$start)
          meta$properties[[property_name]] <- .jrp_literal(b$args[[2L]], descriptors = TRUE)
          if (.jrp_name(property_name) == "valuelabels") {
            if (!is.null(meta$value_labels)) .jrp_error("Duplicate Value Labels property.", position = b$start)
            meta$value_labels <- .jrp_labels(b$args[[2L]])
          }
          if (.jrp_name(property_name) == "missingvaluecodes") {
            meta$missing_value_codes <- .jrp_literal(b$args[[2L]])
            if (!is.atomic(meta$missing_value_codes) && length(meta$missing_value_codes)) .jrp_error("Missing Value Codes must be a literal vector.", position = b$start)
          }
          if (.jrp_name(property_name) %in% c("valueorder", "valueordering")) {
            meta$value_order <- .jrp_literal(b$args[[2L]], descriptors = TRUE)
            if (is.list(meta$value_order) && length(meta$value_order)) meta$metadata_known$value_order <- FALSE
          }
        } else if (bn == "valuelabels") {
          if (length(b$args) != 1L || !is.null(meta$value_labels)) .jrp_error("Unsupported or duplicate Value Labels().", position = b$start)
          meta$value_labels <- .jrp_labels(b$args[[1L]])
          meta$properties[["Value Labels"]] <- .jrp_literal(b$args[[1L]])
        } else if (b$kind == "formula") {
          if (!is.null(meta$formula)) .jrp_error("Duplicate Formula().", position = b$start)
          meta$formula <- b$value
        } else if (bn %in% c("setselected", "setdisplaywidth", "setfieldwidth", "usevaluelabels", "label", "hide", "exclude", "lock")) {
          if (length(b$args) != 1L) .jrp_error("Unsupported column attribute arguments.", position = b$start)
          meta$properties[[b$value]] <- .jrp_literal(b$args[[1L]])
        } else .jrp_error("Unsupported or dynamic New Column() argument.", "jrp_dynamic_error", b$start)
      }
      if (!"model" %in% seen && meta$storage_type == "character") meta$modeling_type <- "Nominal"
      if (!have_values) .jrp_error(paste0("Column '", cn, "' has no stored literal Values(); computing its data is not allowed."), "jrp_dynamic_error", a$start)
      if (meta$storage_type == "numeric" && !is.numeric(v)) .jrp_error(paste0("Numeric column '", cn, "' contains nonnumeric values."), position = a$start)
      if (meta$storage_type == "character" && !is.character(v)) .jrp_error(paste0("Character column '", cn, "' contains noncharacter values."), position = a$start)
      if (length(v) > max_cells || sum(vapply(values, length, numeric(1))) + length(v) > max_cells) .jrp_error("JRP data exceed max_cells.", "jmp_resource_error", a$start)
      if (!is.null(meta$formula)) diagnostic("formula_not_evaluated", cn, "Stored values were imported; the JSL formula was retained without evaluation.")
      if (!is.null(meta$format)) diagnostic("format_preserved", cn, "JSL display format was retained; raw stored values were not reformatted or converted to dates.")
      columns[[cn]] <- meta
      values[[cn]] <- v
    } else if (name %in% c("setproperty", "settablevariable")) {
      if (length(a$args) != 2L || a$args[[1L]]$kind != "string") .jrp_error("Table properties require a literal name and value.", "jrp_dynamic_error", a$start)
      key <- a$args[[1L]]$value
      if (key %in% names(table_properties)) .jrp_error("Duplicate table property.", position = a$start)
      table_properties[[key]] <- .jrp_literal(a$args[[2L]], descriptors = TRUE)
    } else .jrp_error("Unsupported or dynamic New Table() argument.", "jrp_dynamic_error", a$start)
  }
  lengths <- vapply(values, length, numeric(1))
  if (is.null(row_count)) row_count <- if (length(lengths)) lengths[[1L]] else 0
  if (length(lengths) && any(lengths != row_count)) .jrp_error("Stored column lengths and Add Rows() do not agree; implicit filling is not supported.")
  if (row_count * max(length(columns), 1L) > max_cells) .jrp_error("JRP data exceed max_cells.", "jmp_resource_error")
  data <- structure(values, class = "data.frame", row.names = if (row_count) c(NA_integer_, -as.integer(row_count)) else integer())
  diagnostic("jrp_literal_subset", "table", "Only literal embedded table declarations were read. No JSL was executed.")
  # The accepted grammar has no state-setting statement. A new table starts
  # with no excluded/hidden/selected/labelled rows. State setters are rejected.
  rows <- data.frame(row_id = seq_len(row_count), excluded = rep(FALSE, row_count),
                     hidden = rep(FALSE, row_count), selected = rep(FALSE, row_count),
                     labelled = rep(FALSE, row_count), stringsAsFactors = FALSE)
  list(data = data, columns = columns, rows = rows,
       table = list(name = table_name, properties = table_properties),
       scripts = list(jsl_source = text), diagnostics = do.call(rbind, diagnose))
}

# ---- R/read.R ----
# Public API. Parsing never evaluates JSL, R expressions, or shell commands.

.jmp_abort <- function(message, subclass = "jmp_error", ...) {
  stop(structure(c(list(message = message, call = NULL), list(...)),
                 class = unique(c(subclass, "jmp_error", "error", "condition"))))
}

.jmp_flag <- function(x, name) {
  if (!is.logical(x) || length(x) != 1L || is.na(x))
    .jmp_abort(paste0("'", name, "' must be TRUE or FALSE."), "jmp_argument_error")
  x
}

.jmp_limit <- function(x, name) {
  if (!is.numeric(x) || length(x) != 1L || is.na(x) || !is.finite(x) ||
      x < 1 || x > .Machine$integer.max || x != floor(x))
    .jmp_abort(paste0("'", name, "' must be a positive whole number <= ",
                      .Machine$integer.max, "."), "jmp_argument_error")
  as.double(x)
}

.jmp_read_bytes <- function(path, max_bytes) {
  if (!is.character(path) || length(path) != 1L || is.na(path) || !nzchar(path))
    .jmp_abort("'path' must be one nonempty local file path.", "jmp_argument_error")
  if (grepl("^[[:alpha:]][[:alnum:]+.-]*://", path))
    .jmp_abort("Only local files are accepted; URLs are not fetched.", "jmp_argument_error")
  info <- file.info(path)
  if (is.na(info$size) || isTRUE(info$isdir))
    .jmp_abort(paste0("File does not exist or is not a regular file: ", path), "jmp_io_error")
  if (info$size > max_bytes)
    .jmp_abort("File exceeds 'max_bytes'.", "jmp_resource_error")
  con <- tryCatch(file(path, "rb"), error = function(e)
    .jmp_abort(conditionMessage(e), "jmp_io_error"))
  on.exit(close(con), add = TRUE)
  bytes <- readBin(con, "raw", n = as.integer(min(max_bytes + 1, .Machine$integer.max)))
  if (length(bytes) > max_bytes)
    .jmp_abort("File exceeds 'max_bytes'.", "jmp_resource_error")
  bytes
}

.jmp_filter_rows <- function(result, exclude_rows) {
  n <- nrow(result$data)
  result$table$source_nrows <- n
  result$table$excluded_rows_removed <- integer()
  result$table$exclude_rows <- exclude_rows
  if (exclude_rows) {
    flags <- result$rows$excluded
    if (is.null(flags) || !is.logical(flags) || length(flags) != n || anyNA(flags))
      .jmp_abort(paste0("Row exclusion metadata is unavailable; cannot safely remove excluded rows. ",
                       "Use exclude_rows = FALSE to explicitly read all rows."), "jmp_metadata_error")
    keep <- !flags
    result$table$excluded_rows_removed <- result$rows$row_id[flags]
    if (any(flags)) {
      result$data <- result$data[keep, , drop = FALSE]
      rownames(result$data) <- NULL
      result$rows <- result$rows[keep, , drop = FALSE]
      rownames(result$rows) <- NULL
      for (i in seq_along(result$columns)) {
        m <- result$columns[[i]]
        if (!is.null(m$raw_values)) m$raw_values <- m$raw_values[keep]
        if (!is.null(m$row_states)) {
          m$row_states <- m$row_states[keep, , drop = FALSE]
          rownames(m$row_states) <- NULL
        }
        if (!is.null(m$raw_row_states)) {
          width <- as.integer(m$type_bytes[5])
          if (length(m$raw_row_states) != n * width)
            .jmp_abort("Row-state column metadata cannot be aligned after filtering.", "jmp_corrupt_error")
          m$raw_row_states <- as.raw(matrix(m$raw_row_states, nrow = width)[, keep, drop = FALSE])
        }
        result$columns[[i]] <- m
      }
    }
  }
  result$table$returned_nrows <- nrow(result$data)
  result
}

.jmp_finish <- function(result, path, bytes, keep_source, metadata, exclude_rows,
                        missing_codes, factors, ordinal_order, output) {
  if (!is.data.frame(result$data) || length(result$columns) != ncol(result$data))
    .jmp_abort("Reader returned inconsistent column metadata.", "jmp_corrupt_error")
  if (!is.null(result$rows) && nrow(result$rows) != nrow(result$data))
    .jmp_abort("Reader returned inconsistent row metadata.", "jmp_corrupt_error")
  if (is.null(result$diagnostics))
    result$diagnostics <- data.frame(code = character(), scope = character(),
                                     message = character(), stringsAsFactors = FALSE)
  if (is.null(result$scripts)) result$scripts <- list()
  if (is.null(result$table)) result$table <- list()
  result <- .jmp_filter_rows(result, exclude_rows)
  result$source <- list(file = basename(path), size = length(bytes),
                        reader = "jmp2r", version = "0.4.0", backend = "base-R")
  if (keep_source) result$source$bytes <- bytes
  class(result) <- "jmp_dataset"
  converted <- .jmp_analysis_result(result, FALSE, missing_codes, factors, ordinal_order)
  result$data <- converted$data
  result$columns <- converted$columns
  result$diagnostics <- converted$diagnostics
  result$table$missing_codes <- missing_codes
  result$table$factors <- factors
  result$table$ordinal_order <- ordinal_order
  if (output == "data.frame") {
    # Plain-data output omits archival/script metadata. Keep only import notes
    # relevant to values and conversions, not warnings about unused features.
    skip <- result$diagnostics$code %in% c("binary_metadata_partial", "jrp_literal_subset") |
      startsWith(result$diagnostics$message, "Ordinal modeling type is retained, but category order is not explicit;")
    result$diagnostics <- result$diagnostics[!skip, , drop = FALSE]
    rownames(result$diagnostics) <- NULL
  }
  if (nrow(result$diagnostics)) {
    msg <- paste0("JMP import has ", nrow(result$diagnostics),
                  " diagnostic entries. See jmp_metadata(result)$diagnostics.")
    if (metadata == "error")
      .jmp_abort(msg, "jmp_metadata_error", diagnostics = result$diagnostics)
    if (metadata == "warn")
      warning(structure(list(message = msg, call = NULL, diagnostics = result$diagnostics),
                        class = c("jmp_metadata_warning", "warning", "condition")))
  }
  if (output == "data.frame") {
    out <- result$data
    attr(out, "jmp_diagnostics") <- result$diagnostics
    return(out)
  }
  result
}

read_jmp <- function(path, metadata = c("warn", "error", "quiet"),
                     keep_source = TRUE, max_bytes = 512 * 1024^2, max_cells = 1e7,
                     exclude_rows = TRUE, missing_codes = TRUE, factors = TRUE,
                     ordinal_order = c("sort", "error", "appearance"),
                     output = c("data.frame", "dataset")) {
  metadata <- match.arg(metadata)
  output <- match.arg(output)
  ordinal_order <- match.arg(ordinal_order)
  missing_codes <- .jmp_flag(missing_codes, "missing_codes")
  factors <- .jmp_flag(factors, "factors")
  exclude_rows <- .jmp_flag(exclude_rows, "exclude_rows")
  keep_source <- .jmp_flag(keep_source, "keep_source")
  max_bytes <- .jmp_limit(max_bytes, "max_bytes")
  max_cells <- .jmp_limit(max_cells, "max_cells")
  bytes <- .jmp_read_bytes(path, max_bytes)
  result <- .read_jmp_binary(bytes, max_cells = max_cells)
  .jmp_finish(result, path, bytes, keep_source, metadata, exclude_rows,
              missing_codes, factors, ordinal_order, output)
}

read_jrp <- function(path, metadata = c("warn", "error", "quiet"),
                     keep_source = TRUE, max_bytes = 16 * 1024^2, max_cells = 1e7,
                     exclude_rows = TRUE, missing_codes = TRUE, factors = TRUE,
                     ordinal_order = c("sort", "error", "appearance"),
                     output = c("data.frame", "dataset")) {
  metadata <- match.arg(metadata)
  output <- match.arg(output)
  ordinal_order <- match.arg(ordinal_order)
  missing_codes <- .jmp_flag(missing_codes, "missing_codes")
  factors <- .jmp_flag(factors, "factors")
  exclude_rows <- .jmp_flag(exclude_rows, "exclude_rows")
  keep_source <- .jmp_flag(keep_source, "keep_source")
  max_bytes <- .jmp_limit(max_bytes, "max_bytes")
  max_cells <- .jmp_limit(max_cells, "max_cells")
  bytes <- .jmp_read_bytes(path, max_bytes)
  text_bytes <- bytes
  if (length(text_bytes) >= 3L && identical(text_bytes[1:3], as.raw(c(239, 187, 191))))
    text_bytes <- text_bytes[-(1:3)]
  if (any(text_bytes == as.raw(0)))
    .jmp_abort("JRP must be UTF-8 text without NUL bytes; UTF-16 is not supported.",
               "jrp_syntax_error")
  text <- rawToChar(text_bytes)
  if (is.na(iconv(text, from = "UTF-8", to = "UTF-8", sub = NA_character_)))
    .jmp_abort("JRP text is not valid UTF-8.", "jrp_syntax_error")
  Encoding(text) <- "UTF-8"
  result <- .read_jrp_text(text, max_cells = max_cells)
  .jmp_finish(result, path, bytes, keep_source, metadata, exclude_rows,
              missing_codes, factors, ordinal_order, output)
}

read_jmp_file <- function(path, ...) {
  if (!is.character(path) || length(path) != 1L || is.na(path))
    .jmp_abort("'path' must be one local file path.", "jmp_argument_error")
  extension <- tolower(sub("^.*\\.", "", basename(path)))
  switch(extension, jmp = read_jmp(path, ...), jrp = read_jrp(path, ...),
         .jmp_abort("Expected a .jmp or .jrp file extension.", "jmp_argument_error"))
}

jmp_metadata <- function(x) {
  if (is.data.frame(x) && !is.null(attr(x, "jmp_diagnostics", exact = TRUE)))
    return(list(diagnostics = attr(x, "jmp_diagnostics", exact = TRUE)))
  if (!inherits(x, "jmp_dataset"))
    .jmp_abort("'x' must be a jmp2r data frame or jmp_dataset.", "jmp_argument_error")
  x[c("columns", "rows", "table", "scripts", "diagnostics", "source")]
}

print.jmp_dataset <- function(x, ...) {
  cat("<jmp_dataset> ", nrow(x$data), " rows x ", ncol(x$data), " columns\n", sep = "")
  cat("Source: ", x$source$file, " (", x$source$backend, ")\n", sep = "")
  cat("Metadata diagnostics: ", nrow(x$diagnostics), "\n", sep = "")
  print(utils::head(x$data), ...)
  invisible(x)
}

as.data.frame.jmp_dataset <- function(x, row.names = NULL, optional = FALSE, ...) {
  out <- x$data
  if (!is.null(row.names)) row.names(out) <- row.names
  out
}

.jmp_known <- function(meta, field) {
  isTRUE(meta$metadata_known[[field]])
}

as_analysis_data <- function(x, exclude_rows = FALSE, missing_codes = FALSE,
                             factors = FALSE,
                             ordinal_order = c("sort", "error", "appearance")) {
  if (is.data.frame(x)) {
    exclude_rows <- .jmp_flag(exclude_rows, "exclude_rows")
    missing_codes <- .jmp_flag(missing_codes, "missing_codes")
    factors <- .jmp_flag(factors, "factors")
    if (exclude_rows || missing_codes || factors)
      .jmp_abort(paste0("A data frame is already the imported data; further JMP conversions require ",
                       "reading with output = 'dataset' or setting conversion options at import."),
                 "jmp_metadata_error")
    return(x)
  }
  .jmp_analysis_result(x, exclude_rows, missing_codes, factors,
                       match.arg(ordinal_order))$data
}

.jmp_analysis_result <- function(x, exclude_rows, missing_codes, factors, ordinal_order) {
  if (!inherits(x, "jmp_dataset"))
    .jmp_abort("'x' must be a jmp_dataset.", "jmp_argument_error")
  exclude_rows <- .jmp_flag(exclude_rows, "exclude_rows")
  missing_codes <- .jmp_flag(missing_codes, "missing_codes")
  factors <- .jmp_flag(factors, "factors")
  d <- x$data
  columns <- x$columns
  diagnostics <- x$diagnostics
  kept <- rep(TRUE, nrow(d))
  if (exclude_rows) {
    if (is.null(x$rows) || is.null(x$rows$excluded) || anyNA(x$rows$excluded))
      .jmp_abort("Row exclusion metadata is unavailable; cannot apply exclude_rows=TRUE.",
                 "jmp_metadata_error")
    if (!is.logical(x$rows$excluded) || length(x$rows$excluded) != nrow(d))
      .jmp_abort("Invalid row exclusion metadata.", "jmp_metadata_error")
    kept <- !x$rows$excluded
    d <- d[kept, , drop = FALSE]
  }
  for (i in seq_along(d)) {
    m <- x$columns[[i]]
    stored <- if (!is.null(m$stored_values)) m$stored_values[kept] else d[[i]]
    if (missing_codes) {
      if (!.jmp_known(m, "missing_value_codes"))
        .jmp_abort(paste0("Missing-value definitions are unavailable for column '",
                           names(d)[i], "'."), "jmp_metadata_error")
      codes <- m$missing_value_codes
      if (length(codes)) {
        code_values <- stored
        if (!is.null(m$raw_values)) {
          if (length(m$raw_values) != nrow(x$data))
            .jmp_abort("Stored values do not align with the data rows.", "jmp_metadata_error")
          code_values <- m$raw_values[kept]
        }
        d[[i]][code_values %in% codes] <- NA
        m$stored_values <- stored
      }
      m$missing_codes_applied <- TRUE
    }
    if (factors) {
      if (!.jmp_known(m, "modeling_type") || length(m$modeling_type) != 1L ||
          is.na(m$modeling_type))
        .jmp_abort(paste0("Modeling type is unavailable for column '", names(d)[i], "'."),
                   "jmp_metadata_error")
      kind <- tolower(m$modeling_type)
      if (!kind %in% c("continuous", "nominal", "ordinal", "rowstate", "none"))
        .jmp_abort(paste0("Unsupported modeling type: ", m$modeling_type),
                   "jmp_metadata_error")
      if (kind %in% c("nominal", "ordinal")) {
        if (!.jmp_known(m, "value_order") || !.jmp_known(m, "value_labels"))
          .jmp_abort(paste0("Category metadata is unavailable for column '",
                             names(d)[i], "'."), "jmp_metadata_error")
        values <- stored
        # Keep previously converted missing values missing when conversion is
        # requested again; labels are never treated as the original codes.
        values[is.na(d[[i]])] <- NA
        lev <- m$value_order
        order_source <- "jmp"
        if (!length(lev)) {
          if (kind == "ordinal" && ordinal_order == "error")
            .jmp_abort(paste0("Ordinal column '", names(d)[i],
                               "' has no explicit Value Order."), "jmp_metadata_error")
          lev <- unique(values[!is.na(values)])
          if (kind == "ordinal" && ordinal_order == "sort") {
            lev <- sort(lev)
            order_source <- "r_sort"
          } else order_source <- "first_appearance"
          if (kind == "ordinal") diagnostics <- rbind(diagnostics, data.frame(
            code = "ordinal_order_inferred", scope = names(d)[i],
            message = if (ordinal_order == "sort")
              "No explicit JMP category order; ordered factor uses R's standard sorted order (character order depends on the R locale)."
            else "No explicit JMP category order; ordered factor uses first appearance in the returned data.",
            stringsAsFactors = FALSE))
        }
        if (isTRUE(m$missing_codes_applied) && length(m$missing_value_codes))
          lev <- lev[!lev %in% m$missing_value_codes]
        if (anyNA(lev) || anyDuplicated(lev))
          .jmp_abort("Category levels must be unique and non-missing.", "jmp_metadata_error")
        observed <- unique(values[!is.na(values)])
        if (any(!observed %in% lev))
          .jmp_abort(paste0("Value Order omits observed values in column '", names(d)[i], "'."),
                     "jmp_metadata_error")
        labels <- as.character(lev)
        vl <- m$value_labels
        if (length(vl)) {
          if (length(vl$values) != length(vl$labels) || anyDuplicated(vl$values))
            .jmp_abort("Invalid value-label metadata.", "jmp_metadata_error")
          hit <- match(lev, vl$values)
          labels[!is.na(hit)] <- vl$labels[hit[!is.na(hit)]]
        }
        if (anyNA(labels) || anyDuplicated(labels))
          .jmp_abort("Category labels would merge distinct stored values; conversion stopped.",
                     "jmp_metadata_error")
        d[[i]] <- factor(values, levels = lev, labels = labels, ordered = kind == "ordinal")
        m$stored_values <- stored
        m$r_levels <- lev
        m$r_level_labels <- labels
        m$r_level_order_source <- order_source
      }
    }
    columns[[i]] <- m
  }
  list(data = d, columns = columns, diagnostics = diagnostics)
}
